/// The `PINCM` register number for one pin, or `None` if this part has no such pin.
///
/// `chip` is matched lowercased, as [`crate::Bench::chip`] returns it. The value is TI's
/// one-based `PINCM<n>`; see the module docs for how to turn it into an address.
#[must_use]
pub fn pincm(chip: &str, port: u8, index: u8) -> Option<u8> {
    let pins = PARTS.iter().find(|(name, _)| *name == chip).map(|(_, pins)| *pins)?;
    pins.iter()
        .find(|(p, n, _)| *p == port && *n == index)
        .map(|(_, _, pincm)| *pincm)
}

/// Every pin this part brings out, as `(port, index)`, lowest first.
#[must_use]
pub fn pins(chip: &str) -> Option<impl Iterator<Item = (u8, u8)>> {
    let pins = PARTS.iter().find(|(name, _)| *name == chip).map(|(_, pins)| *pins)?;
    Some(pins.iter().map(|(port, index, _)| (*port, *index)))
}

/// Whether the catalog knows this part at all.
#[must_use]
pub fn known(chip: &str) -> bool {
    PARTS.iter().any(|(name, _)| *name == chip)
}

#[cfg(test)]
mod tests {
    use super::{known, pincm};

    /// The part this was developed against, where `PINCM` happens to be the pin number plus one.
    #[test]
    fn the_regular_case() {
        assert_eq!(pincm("mspm0l1306", 0, 0), Some(1));
        assert_eq!(pincm("mspm0l1306", 0, 11), Some(12));
    }

    /// **The reason this is a table.** Two ports, and the mapping is not affine in either.
    #[test]
    fn the_irregular_case() {
        assert_eq!(pincm("mspm0l2228", 0, 1), Some(2));
        assert_eq!(pincm("mspm0l2228", 0, 2), Some(7));
        assert_eq!(pincm("mspm0l2228", 1, 0), Some(12));
    }

    #[test]
    fn an_unknown_part_or_pin_is_none() {
        assert!(!known("stm32f103"));
        assert_eq!(pincm("stm32f103", 0, 0), None);
        assert_eq!(pincm("mspm0l1306", 2, 0), None);
    }
}
